observation.command:
cd /workspace/01-frontend && docker run --rm -v /workspace/01-frontend:/w -w /w node:20-bookworm sh -c '
HUSKY=0 npm ci --workspace shell --include-workspace-root=false >/dev/null 2>&1
(node -e "const fs=require(\"fs\"); const p=require(\"path\"); const out={}; (function w(d){for(const e of fs.readdirSync(d,{withFileTypes:true})){if(e.name===\"node_modules\")continue; if(e.name.startsWith(\".\"))continue; const f=p.join(d,e.name); if(e.isDirectory())w(f); else if(e.isFile()&&e.name===\"package.json\"){try{out[p.relative(\"/w/node_modules\",f).replace(/\/package.json$/,\"\")]=JSON.parse(fs.readFileSync(f)).version}catch(x){}}}})(\"/w/node_modules\"); console.log(JSON.stringify(out))" > /tmp/subset.json) 2>/dev/null
rm -rf node_modules
HUSKY=0 npm ci >/dev/null 2>&1
node -e "const fs=require(\"fs\"); const p=require(\"path\"); const out={}; (function w(d){for(const e of fs.readdirSync(d,{withFileTypes:true})){if(e.name===\"node_modules\")continue; if(e.name.startsWith(\".\"))continue; const f=p.join(d,e.name); if(e.isDirectory())w(f); else if(e.isFile()&&e.name===\"package.json\"){try{out[p.relative(\"/w/node_modules\",f).replace(/\/package.json$/,\"\")]=JSON.parse(fs.readFileSync(f)).version}catch(x){}}}})(\"/w/node_modules\"); console.log(JSON.stringify(out))" > /tmp/full.json
node -e "
const s=require(\"/tmp/subset.json\"); const f=require(\"/tmp/full.json\");
const diffs=[]; const missing=[];
for(const k of Object.keys(f)){ if(!(k in s)) missing.push(k+\"@\"+f[k]); else if(s[k]!==f[k]) diffs.push(k+\": \"+s[k]+\" -> \"+f[k]); }
console.log(\"VERSION DIFFS:\"); diffs.slice(0,20).forEach(x=>console.log(\"  \"+x));
console.log(\"MISSING IN SUBSET (\"+missing.length+\"): \"); missing.slice(0,25).forEach(x=>console.log(\"  \"+x));
"'
